public static AAXProdOrderEstimatedBusinessEventContract newFromProdTable(ProdTable _prodTable)
{
    var contract = new AAXProdOrderEstimatedBusinessEventContract();
    contract.initialize(_prodTable);

    return contract;
}

/// <summary>
